import { h, SVG_NS } from './dom.ts'

type Pose = 'stand' | 'jump' | 'flat' | 'look'

type Facing = 'left' | 'right'

interface Art {
  box: readonly [number, number, number, number]
  left: number
  eyes: string
  ink: string
  belly: string
}

export interface Mascot {
  element: HTMLElement
  dispose: () => void
}

