const HOP_HEIGHT = 70
const WAKE_HEIGHT = 110
const CROUCH_MS = 110
const AIR_MS = 420
const LAND_MS = 140
const TURN_MS = 260
const NAP_MS = 3600
const Z_COUNT = 3
const Z_GLYPH = 'M0 0h5v1H0zM3 1h1v1H3zM2 2h1v1H2zM1 3h1v1H1zM0 4h5v1H0z'

