const SPARK =
  'M480 710V711H476V712H477V714H476V718H477V727H476V728H477V729H481V742H482V746H490V745H493V730H492V729H491V727H490V726H487V711H486V710ZM443 726V727H440V729H438V730H436V735H435V736H436V737H437V738H438V739H439V740H441V745H442V746H445V745H446V746H447V750H446V751H447V752H452V758H455V760H456V761H460V760H461V758H463V757H464V752H463V746H457V740H453V739H452V734H447V730H446V729H445V727H444V726ZM417 763V774H424V779H425V780H435V783H436V786H448V777H445V776H444V775H443V774H441V773H436V772H435V770H436V769H435V768H427V767H426V763Z'
const DASH: Art = {
  box: [466, 936, 156, 16],
  left: -156,
  eyes: '',
  ink: '',
  belly:
    'M581 936V944H621V943H622V936ZM466 944V952H504V947H503V944ZM524 944V952H560V944Z',
}

function sprite(
  className: string,
  art: Art,
  extra: readonly (readonly [string, string])[] = [],
): SVGSVGElement {
  const svg = document.createElementNS(SVG_NS, 'svg')
  const layers: readonly (readonly [string, string])[] = [
    ['mascot-eyes', art.eyes],
    ['mascot-ink', art.ink],
    ['mascot-belly', art.belly],
    ...extra,
  ]

  svg.setAttribute('class', className)
  svg.setAttribute('viewBox', art.box.join(' '))
  svg.style.setProperty('--left', String(art.left))
  svg.style.setProperty('--width', String(art.box[2]))

  for (const [part, d] of layers) {
    if (!d) continue

    const path = document.createElementNS(SVG_NS, 'path')

    path.setAttribute('class', part)
    path.setAttribute('d', d)
    svg.append(path)
  }

  return svg
}

function zGlyph(index: number): SVGSVGElement {
  const svg = document.createElementNS(SVG_NS, 'svg')
  const path = document.createElementNS(SVG_NS, 'path')

  svg.setAttribute('class', 'mascot-z')
  svg.setAttribute('viewBox', '0 0 5 5')
  svg.style.setProperty('--index', String(index))
  path.setAttribute('d', Z_GLYPH)
  svg.append(path)

  return svg
}

export function mascot(): Mascot {
  const body = h(
    'div',
    { class: 'mascot-body' },
    POSE_NAMES.map(pose => {
      const svg = sprite(
        'mascot-pose',
        POSES[pose],
        pose === 'jump' ? [['mascot-spark', SPARK]] : [],
      )

      svg.dataset.pose = pose

      return svg
    }),
  )
  const actor = h(
    'div',
    { class: 'mascot-actor', 'data-facing': 'left' },
    sprite('mascot-dash', DASH),
    body,
    h(
      'div',
      { class: 'mascot-zzz' },
      Array.from({ length: Z_COUNT }, (_, index) => zGlyph(index)),
    ),
  )
  const element = h(
    'div',
    { class: 'mascot', 'data-pose': 'stand', 'aria-hidden': 'true' },
    actor,
  )
  const animations = new Set<Animation>()
  let isOn = true
  let x = 0
  let facing: Facing = 'left'
  let timer = 0
  let wake: (() => void) | null = null

  const show = (pose: Pose): void => {
    element.dataset.pose = pose
  }

  const wait = (ms: number): Promise<void> =>
    new Promise(resolve => {
      if (!isOn) return resolve()

      wake = resolve
      timer = window.setTimeout(resolve, ms)
    })

  const animate = (
    target: HTMLElement,
    keyframes: Keyframe[],
    options: KeyframeAnimationOptions,
  ): Promise<void> =>
    new Promise(resolve => {
      if (!isOn) return resolve()

      const animation = target.animate(keyframes, options)
      const done = (): void => {
        animations.delete(animation)
        resolve()
      }

      animations.add(animation)
      animation.addEventListener('finish', done)
      animation.addEventListener('cancel', done)
    })

  const bounce = (height: number): Promise<void> => {
    const total = CROUCH_MS + AIR_MS + LAND_MS
    const at = (ms: number): number => ms / total

    return animate(
      body,
      [
        { '--mascot-y': '0', '--mascot-squash': '1', easing: 'ease-out' },
        {
          '--mascot-y': '0',
          '--mascot-squash': '0.82',
          offset: at(CROUCH_MS),
          easing: 'ease-out',
        },
        {
          '--mascot-y': String(height),
          '--mascot-squash': '1.06',
          offset: at(CROUCH_MS + AIR_MS / 2),
          easing: 'ease-in',
        },
        {
          '--mascot-y': '0',
          '--mascot-squash': '1',
          offset: at(CROUCH_MS + AIR_MS),
          easing: 'ease-out',
        },
        {
          '--mascot-y': '0',
          '--mascot-squash': '0.86',
          offset: at(CROUCH_MS + AIR_MS + LAND_MS / 2),
        },
        { '--mascot-y': '0', '--mascot-squash': '1' },
      ],
      { duration: total },
    )
  }

  const leap = async (height: number): Promise<void> => {
    const landed = bounce(height)

    await wait(CROUCH_MS)
    show('jump')
    element.classList.add('is-airborne')
    await wait(AIR_MS)
    element.classList.remove('is-airborne')
    show('stand')
    await landed
  }

  const hop = async (): Promise<void> => {
    const from = x

    x += facing === 'left' ? -HOP : HOP
    actor.style.setProperty('--mascot-x', String(x))
    void animate(
      actor,
      [{ '--mascot-x': String(from) }, { '--mascot-x': String(x) }],
      { duration: AIR_MS, delay: CROUCH_MS, fill: 'backwards' },
    )
    await leap(HOP_HEIGHT)
  }

  const hops = async (count: number): Promise<void> => {
    for (let index = 0; index < count; index++) await hop()
  }

  const turn = async (): Promise<void> => {
    facing = facing === 'left' ? 'right' : 'left'
    actor.dataset.facing = facing
    await wait(TURN_MS)
  }

  const nap = async (): Promise<void> => {
    show('flat')
    element.classList.add('is-sleeping')
    await wait(NAP_MS)
    element.classList.remove('is-sleeping')
    element.classList.add('is-surprised')
    await leap(WAKE_HEIGHT)
    element.classList.remove('is-surprised')
  }

  const play = async (): Promise<void> => {
    while (isOn) {
      show('stand')
      await wait(1100)
      show('look')
      await wait(1600)
      show('stand')
      await wait(380)
      await hops(2)
      await wait(420)
      await turn()
      await hops(4)
      await wait(420)
      await turn()
      await hops(2)
      await wait(600)
      await nap()
      await wait(900)
    }
  }

  if (!matchMedia('(prefers-reduced-motion: reduce)').matches) void play()

  return {
    element,
    dispose: () => {
      isOn = false
      window.clearTimeout(timer)
      wake?.()

      for (const animation of animations) animation.cancel()
    },
  }
}
